		declCache: map[string][]*decl{},
	}
	b.manifest(changes)
	b.resolve(changes)
	b.expand()

	env := &Envelope{
		SchemaVersion:  SchemaVersion,
		Provider:       Provider{Name: providerName, Version: opts.Version, Language: providerLanguage},
		BaseSHA:        base,
		Files:          b.files,
		Expansions:     b.exps,
