+		Role:      RoleCaller,
+		Priority:  priorityFor(s.target),
+		Symbol:    s.target.symbol,
+		Scope:     s.target.scope,
+		File:      s.rel,
+		StartLine: start,
+		EndLine:   end,
+		Content:   b.slice(s.rel, start, end),
+		Details:   details,
+	})
