	for _, p := range b.idx.pkgs {
		if p.TypesInfo == nil || p.Fset == nil {
			continue
		}
		for id, obj := range p.TypesInfo.Uses {
			if obj == nil {
				continue
			}
			target := byPos[obj.Pos()]
			if target == nil {
				continue
