// File is one changed file in the manifest.
type File struct {
	Path      string   `json:"path"`
	Class     Class    `json:"class"`
	Generated bool     `json:"generated,omitempty"`
	Symbols   []string `json:"symbols,omitempty"`
}

// SchemaVersion is the version of the wire format this package writes. The
// consumer refuses a version it does not know rather than reading fields that
// may have moved.
const SchemaVersion = 1

// Role is what an expansion is. The vocabulary belongs to the consumer, which
// ranks by role without parsing the code an expansion carries. Inventing a
// role here would rank it last on the far side, so the set below is closed.
type Role string

// RoleSibling is another implementation of an interface a changed type
// implements.
RoleSibling Role = "sibling"

// changedContextCommand serves `context --changed <ref>`: the context envelope
// for a whole change, for a reviewer that already has the diff. It is a
// different job from the per-symbol pack above it, and the difference that
// matters is the budget. The pack trims to fit one prompt; the envelope leaves
// ranking and truncation to whatever consumes it, so trimming here would throw
// away context that consumer had room for.
func changedContextCommand(ref, root string, positional []string, flags map[string]string) error {
	if len(positional) > 0 {
		return usageErrorf("context --changed takes no symbol argument (got %q)", positional[0])
	}
	if flags["--budget"] != "" {
		return usageErrorf("--budget does not apply to --changed; expansions are emitted whole for the consumer to rank")
	}
	env, err := changectx.Build(changectx.Options{
		Root:    root,
		BaseRef: ref,
		Version: version.Version(),
	})
	if err != nil {
		return err
	}
	if flags["--json"] != "" {
		emitEnvelope(true, "", env)
		return nil
	}
	fmt.Print(changectx.Summary(env))
	return nil
}

// changedFixtureRepo commits the module and leaves one function edited.
func changedFixtureRepo(t *testing.T) string {
	t.Helper()
	if _, err := exec.LookPath("git"); err != nil {
		t.Skip("git is not installed")
	}
	t.Setenv("GOWORK", "off")
	dir := t.TempDir()
	if resolved, err := filepath.EvalSymlinks(dir); err == nil {
		dir = resolved
	}
	for rel, content := range changedFixtureBase {
		if err := os.WriteFile(filepath.Join(dir, rel), []byte(content), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	run := func(args ...string) {
