// resolve maps each changed hunk to the declaration that encloses it.
func (b *builder) resolve(changes []change) {
	byPath := map[string]change{}
	anyGo := false
	for _, c := range changes {
		byPath[c.path] = c
		if strings.HasSuffix(c.path, ".go") {
			anyGo = true
		}
	}
	if !anyGo {
		return
	}
	idx, notes := loadModule(b.repo)
	b.idx = idx
	b.notes = append(b.notes, notes...)

	for i := range b.files {
		f := &b.files[i]
		if !b.reviewable(i) || byPath[f.Path].deleted() {
			continue
		}
		ranges, err := hunkRanges(b.repo, b.base, f.Path)
		if err != nil {
			b.notes = append(b.notes, "no diff hunks for "+f.Path+": "+err.Error())
			continue
		}
		if len(ranges) == 0 {
			ranges = b.wholeFileRange(f.Path)
		}
		b.ranges[f.Path] = ranges
		b.resolveFile(f, ranges)
	}
	sort.Slice(b.decls, func(i, j int) bool { return declLess(b.decls[i], b.decls[j]) })
}

func (b *builder) resolveFile(f *File, ranges []lineRange) {
	abs := filepath.Join(b.repo, filepath.FromSlash(f.Path))
	unit := b.idx.unit(abs)
	if unit == nil || unit.syntax == nil {
		b.notes = append(b.notes, "could not parse "+f.Path+"; its symbols were not resolved")
		return
	}
	for _, d := range b.declsForRel(f.Path) {
		hit := false
		for _, r := range ranges {
			if d.overlaps(r) {
				hit = true
				break
			}
		}
		if !hit {
			continue
		}
		d.changed = d.countChanged(ranges)
		resolveObject(d)
		b.decls = append(b.decls, d)
		f.Symbols = append(f.Symbols, d.symbol)
	}
	f.Symbols = sortedUnique(f.Symbols)
}

// sortExpansions puts the output in the order the consumer will rank it: by
// role, then by the provider's own hint, then by position. The last three keys
// exist only to break ties the same way twice.
func sortExpansions(exps []Expansion) {
	sort.SliceStable(exps, func(i, j int) bool {
		a, c := exps[i], exps[j]
		if ra, rc := roleRank[a.Role], roleRank[c.Role]; ra != rc {
			return ra < rc
		}
		if a.Priority != c.Priority {
			return a.Priority > c.Priority
		}
		if a.File != c.File {
			return a.File < c.File
		}
		if a.StartLine != c.StartLine {
			return a.StartLine < c.StartLine
		}
		if a.Symbol != c.Symbol {
			return a.Symbol < c.Symbol
		}
		return a.Content < c.Content
	})
}

// baseFiles is the committed state of the fixture module. The change under
// test edits one method of Store, which is enough to exercise every role: the
// method has a caller, a test, a named type in its signature, and a sibling
// implementation of the interface its receiver satisfies.
var baseFiles = map[string]string{
	"go.mod": "module example.com/fix\n\ngo 1.21\n",
	"types.go": `package fix

import "errors"

// Record is one stored row.
type Record struct {
	ID string
}

// ErrEmpty reports a record with no identity.
var ErrEmpty = errors.New("empty record")

// Writer stores records.
type Writer interface {
	Insert(r Record) error
}
`,
	"store.go": `package fix

// Store counts the records it was given.
type Store struct {
	n int
}

// Insert stores a record.
func (s *Store) Insert(r Record) error {
	if r.ID == "" {
		return ErrEmpty
	}
	s.n++
	return nil
}
`,
	"mem.go": `package fix

// MemStore keeps records in memory.
type MemStore struct {
	items []Record
}

// Insert stores a record in memory.
func (m *MemStore) Insert(r Record) error {
	m.items = append(m.items, r)
	return nil
}
`,
	"use.go": `package fix

// Save writes a record through a store.
func Save(s *Store, r Record) error {
	return s.Insert(r)
}
`,
	"store_test.go": `package fix

import "testing"

func TestInsert(t *testing.T) {
	var s Store
	if err := s.Insert(Record{ID: "a"}); err != nil {
		t.Fatalf("insert: %v", err)
	}
}
`,
}

// changedStore rewrites Insert so the diff lands inside one method.
const changedStore = `package fix

// Store counts the records it was given.
type Store struct {
	n int
}

// Insert stores a record.
func (s *Store) Insert(r Record) error {
	if r.ID == "" {
		return ErrEmpty
	}
	if len(r.ID) > 64 {
		return ErrEmpty
	}
	s.n++
	return nil
