// classify decides the manifest entry for one changed path. The order of the
// tests below is the precedence: the first answer that applies wins, so a
// generated lock file reports as a lock file and still carries the generated
// flag.
func classify(repo string, c change) (Class, bool) {
	p := filepath.ToSlash(c.path)
	base := path.Base(p)
	gen := isGeneratedName(base) || (!c.deleted() && hasGeneratedHeader(repo, p))

	switch {
	case hasSegment(p, "vendor") || strings.HasPrefix(p, "third_party/"):
		return ClassVendored, gen
	case lockfileNames[base]:
		return ClassLockfile, gen
	case isMigration(p, base):
		return ClassMigration, gen
	case gen:
		return ClassGenerated, true
	case strings.HasSuffix(base, "_test.go") || hasSegment(p, "testdata"):
		return ClassTest, gen
	case strings.HasSuffix(base, ".go"):
		return ClassSource, gen
	}
	return ClassOther, gen
}

// hasGeneratedHeader reports whether the file carries the convention line
// above its first line of code. Reading stops at that first line, which is why
// a mention of the convention inside a function body cannot trigger it.
func hasGeneratedHeader(repo, rel string) bool {
	data, err := os.ReadFile(filepath.Join(repo, filepath.FromSlash(rel)))
	if err != nil {
		return false
	}
	inBlock := false
	for i, line := range strings.Split(string(data), "\n") {
		if i >= headerScanLines {
			return false
		}
		t := strings.TrimSpace(line)
		if t == "" {
			continue
		}
		switch {
		case inBlock:
			if generatedHeaderRe.MatchString(t) {
				return true
			}
			if strings.Contains(t, "*/") {
				inBlock = false
			}
		case strings.HasPrefix(t, "/*"):
			if generatedHeaderRe.MatchString(t) {
				return true
			}
			if !strings.Contains(t[2:], "*/") {
				inBlock = true
			}
		case strings.HasPrefix(t, "//"):
			if generatedHeaderRe.MatchString(t) {
				return true
			}
		default:
			return false
		}
	}
	return false
}

// expandHistory emits the recent history of the changed line spans. It is
// cheap, and it stops a whole class of bad review comment: the suggestion to
// undo a deliberate fix.
func (b *builder) expandHistory() {
	for _, f := range b.files {
		ranges := b.ranges[f.Path]
		for i, r := range ranges {
			if i >= historyRangesPerFile {
				break
			}
			out, err := logLineHistory(b.repo, f.Path, r, historyRevisions)
			if err != nil || strings.TrimSpace(out) == "" {
				continue
			}
			d := b.declCovering(f.Path, r)
			e := Expansion{
				Role:      RoleHistory,
				File:      f.Path,
				StartLine: r.start,
				EndLine:   r.end,
				Content:   out,
				Details: map[string]string{
					"kind":      "line-history",
					"lines":     fmt.Sprintf("%d-%d", r.start, r.end),
					"revisions": strconv.Itoa(historyRevisions),
				},
			}
			if d != nil {
				e.Priority = priorityFor(d)
				e.Symbol = d.symbol
				e.Scope = d.scope
			}
			b.add(e)
		}
		b.expandRemovedHistory(f.Path)
	}
}

// expandRemovedHistory traces the lines this change deletes.
//
// A deletion is where history earns its place. The lines are gone, so nothing
// in the diff says why they were there, and a guard added on purpose reads
// exactly like a tidy simplification. Tracing the span against the base
// revision recovers the commit that introduced it, and with it the reason.
func (b *builder) expandRemovedHistory(path string) {
	ranges, err := removedRanges(b.repo, b.base, path)
	if err != nil {
		return
	}
	for i, r := range ranges {
		if i >= historyRangesPerFile {
			break
		}
		out, err := logRemovedHistory(b.repo, b.base, path, r, historyRevisions)
		if err != nil || strings.TrimSpace(out) == "" {
			continue
		}
		b.add(Expansion{
			Role: RoleHistory,
			// Above the surviving lines' history: why something was removed
			// is a sharper question than why it is still there.
			Priority:  1,
			File:      path,
			StartLine: r.start,
			EndLine:   r.end,
			Content:   out,
			Details: map[string]string{
				"kind":      "removed-line-history",
				"lines":     fmt.Sprintf("%d-%d at the base revision", r.start, r.end),
				"revisions": strconv.Itoa(historyRevisions),
			},
		})
	}
}

// expandTypes emits the definition of each named type a changed signature
// mentions. A signature the reviewer cannot resolve is a signature they have
// to guess at.
func (b *builder) expandTypes() {
	seen := map[token.Pos]bool{}
	for _, d := range b.decls {
		if d.obj == nil {
			continue
		}
		sig, ok := d.obj.Type().(*types.Signature)
		if !ok {
			continue
		}
		for _, named := range signatureNamed(sig) {
			obj := named.Obj()
			if obj == nil || obj.Pkg() == nil || seen[obj.Pos()] {
				continue
			}
			seen[obj.Pos()] = true
			target := b.declFor(obj)
			if target == nil || b.isChanged(target) {
				continue // its own declaration already carries the change
			}
			b.add(Expansion{
				Role:      RoleType,
				Priority:  priorityFor(d),
				Symbol:    target.symbol,
				Scope:     target.scope,
				File:      target.rel,
				StartLine: target.start,
				EndLine:   target.end,
				Content:   b.slice(target.rel, target.start, target.end),
				Details: map[string]string{
					"kind":         "type",
					"referencedBy": d.scope,
				},
			})
		}
	}
}

// expandSiblings emits the other implementations of an interface a changed
// type satisfies. It answers the question a diff cannot: whether the same
// change is owed to the types that sit beside this one.
func (b *builder) expandSiblings() {
	changed := b.changedNamedTypes()
	if len(changed) == 0 || b.idx == nil {
		return
	}
	ifaces, concrete := b.moduleTypes()
	emitted := map[string]bool{}
	for _, ct := range changed {
		for _, iface := range ifaces {
			it, ok := iface.named.Underlying().(*types.Interface)
			if !ok || it.NumMethods() == 0 || !satisfies(ct.named, it) {
				continue
			}
			b.addSiblings(ct, iface, it, concrete, emitted)
		}
	}
}

func (b *builder) addSiblings(ct, iface namedType, it *types.Interface, concrete []namedType, emitted map[string]bool) {
	kept := 0
	skipped := 0
	for _, other := range concrete {
		if other.named == ct.named || other.decl == nil || !satisfies(other.named, it) {
			continue
		}
		key := ct.decl.scope + "|" + other.decl.scope
		if emitted[key] {
			continue
		}
		if kept >= siblingsPerInterface {
			skipped++
			continue
		}
		emitted[key] = true
		kept++
		b.add(Expansion{
			Role:      RoleSibling,
			Priority:  priorityFor(ct.decl),
			Symbol:    other.decl.symbol,
			Scope:     other.decl.scope,
			File:      other.decl.rel,
			StartLine: other.decl.start,
			EndLine:   other.decl.end,
			Content:   b.slice(other.decl.rel, other.decl.start, other.decl.end),
			Details: map[string]string{
				"kind":      "implementation",
				"interface": iface.decl.scope,
				"peerOf":    ct.decl.scope,
			},
		})
	}
	if skipped > 0 {
		b.notes = append(b.notes, fmt.Sprintf(
			"%d further implementation(s) of %s were not expanded (cap %d per interface)",
			skipped, iface.decl.scope, siblingsPerInterface))
	}
}

// changedNamedTypes returns the named types the change touches: types declared
// in a changed declaration, and the receiver types of changed methods.
func (b *builder) changedNamedTypes() []namedType {
	seen := map[token.Pos]bool{}
	var out []namedType
	for _, d := range b.decls {
		var named *types.Named
		switch {
		case d.kind == "type" && d.obj != nil:
			named, _ = d.obj.Type().(*types.Named)
		case d.receiver != "" && d.unit != nil && d.unit.pkg != nil && d.unit.pkg.Types != nil:
			if obj := d.unit.pkg.Types.Scope().Lookup(d.receiver); obj != nil {
				named, _ = obj.Type().(*types.Named)
			}
		}
		if named == nil || named.Obj() == nil || seen[named.Obj().Pos()] {
			continue
		}
		target := b.declFor(named.Obj())
		if target == nil {
			continue
		}
		seen[named.Obj().Pos()] = true
		out = append(out, namedType{named: named, decl: target})
	}
	return out
}

// moduleTypes returns every named type declared in the loaded module, split
// into interfaces and the rest. Only module types are considered: matching
// against the standard library would report every type in the repository as a
// sibling under error or fmt.Stringer.
func (b *builder) moduleTypes() (ifaces, concrete []namedType) {
	if b.idx == nil {
		return nil, nil
	}
	seen := map[token.Pos]bool{}
	for _, p := range b.idx.pkgs {
		if p.Types == nil {
			continue
		}
		scope := p.Types.Scope()
		names := append([]string(nil), scope.Names()...)
		sort.Strings(names)
		for _, n := range names {
			tn, ok := scope.Lookup(n).(*types.TypeName)
			if !ok || tn.IsAlias() {
				continue
			}
			named, ok := tn.Type().(*types.Named)
			if !ok || seen[tn.Pos()] {
				continue
			}
			seen[tn.Pos()] = true
			d := b.declFor(tn)
			if d == nil {
				continue
			}
			entry := namedType{named: named, decl: d}
			if _, isIface := named.Underlying().(*types.Interface); isIface {
				ifaces = append(ifaces, entry)
			} else {
				concrete = append(concrete, entry)
			}
		}
	}
	sort.Slice(ifaces, func(i, j int) bool { return ifaces[i].decl.scope < ifaces[j].decl.scope })
	sort.Slice(concrete, func(i, j int) bool { return concrete[i].decl.scope < concrete[j].decl.scope })
	return ifaces, concrete
}

// signatureNamed collects the named types a signature mentions, following the
// type constructors that wrap them. It stops at a named type rather than
// descending into it, so a struct field's type is not pulled in.
func signatureNamed(sig *types.Signature) []*types.Named {
	var out []*types.Named
	seen := map[*types.Named]bool{}
	var walk func(t types.Type, depth int)
	walk = func(t types.Type, depth int) {
		if t == nil || depth > 6 {
			return
		}
		switch v := t.(type) {
		case *types.Named:
			if !seen[v] {
				seen[v] = true
				out = append(out, v)
			}
		case *types.Pointer:
			walk(v.Elem(), depth+1)
		case *types.Slice:
			walk(v.Elem(), depth+1)
		case *types.Array:
			walk(v.Elem(), depth+1)
		case *types.Chan:
			walk(v.Elem(), depth+1)
		case *types.Map:
			walk(v.Key(), depth+1)
			walk(v.Elem(), depth+1)
		case *types.Signature:
			walk(v.Params(), depth+1)
			walk(v.Results(), depth+1)
		case *types.Tuple:
			for i := 0; i < v.Len(); i++ {
				walk(v.At(i).Type(), depth+1)
			}
		}
	}
	walk(sig.Params(), 0)
	walk(sig.Results(), 0)
	if recv := sig.Recv(); recv != nil {
		walk(recv.Type(), 0)
	}
	return out
}

// expandUses emits the caller and test roles. Both come from the same walk:
// every identifier the type checker resolved to a changed declaration.
//
// Call sites of unexported declarations count. Gating them out was the first
// shape of this and it was wrong twice over. It dropped exactly the case the
// role exists for, since most signature changes are to unexported functions
// used within their own package, and it was inconsistent with the test role
// beside it, which never had the gate: a reviewer was shown the test calling
// a changed unexported function and not the production code calling it.
// Exportedness is a ranking input rather than a filter, and priorityFor
// already scores it, so the consumer's budget drops these first when space is
// short instead of never seeing them.
func (b *builder) expandUses() {
	sites := b.collectUses()
	seenTest := map[string]bool{}
	for _, s := range sites {
		if strings.HasSuffix(s.rel, "_test.go") {
			b.addTestSite(s, seenTest)
			continue
		}
		b.addCallerSite(s)
	}
}

func (b *builder) addCallerSite(s useSite) {
	start := max(s.line-callerContextLines, 1)
	end := s.line + callerContextLines
	details := map[string]string{"kind": "call-site", "line": strconv.Itoa(s.line)}
	if encl := b.enclosingAt(s.rel, s.line); encl != nil {
		details["callerSymbol"] = encl.scope
		details["callerKind"] = encl.kind
	}
	b.add(Expansion{
		Role:      RoleCaller,
		Priority:  priorityFor(s.target),
		Symbol:    s.target.symbol,
		Scope:     s.target.scope,
		File:      s.rel,
		StartLine: start,
		EndLine:   end,
		Content:   b.slice(s.rel, start, end),
		Details:   details,
	})
}

// addTestSite emits the whole test function that reaches a changed symbol. The
// assertions are the part that says what the symbol is supposed to do, and
// they are usually below the call.
func (b *builder) addTestSite(s useSite, seen map[string]bool) {
	encl := b.enclosingAt(s.rel, s.line)
	if encl == nil {
		return
	}
	key := encl.rel + ":" + encl.symbol + ":" + s.target.scope
	if seen[key] {
		return
	}
	seen[key] = true
	b.add(Expansion{
		Role:      RoleTest,
		Priority:  priorityFor(s.target),
		Symbol:    encl.symbol,
		Scope:     encl.scope,
		File:      encl.rel,
		StartLine: encl.start,
		EndLine:   encl.end,
		Content:   b.slice(encl.rel, encl.start, encl.end),
		Details: map[string]string{
			"kind":    "test",
			"covers":  s.target.scope,
			"testFor": s.target.symbol,
		},
	})
}

// collectUses walks the type information of every loaded package variant and
// keeps the identifiers that resolve to a changed declaration. The result is
// sorted because the walk is over maps, and an envelope whose order depends on
// map iteration cannot be compared with itself.
func (b *builder) collectUses() []useSite {
	byPos := b.changedByPos()
	if len(byPos) == 0 || b.idx == nil {
		return nil
	}
	seen := map[string]bool{}
	var out []useSite
	for _, p := range b.idx.pkgs {
		if p.TypesInfo == nil || p.Fset == nil {
			continue
		}
		for id, obj := range p.TypesInfo.Uses {
			if obj == nil {
				continue
			}
			target := byPos[obj.Pos()]
			if target == nil {
				continue
			}
			pos := p.Fset.Position(id.Pos())
			rel, ok := b.rel(pos.Filename)
			if !ok {
				continue
			}
			if rel == target.rel && pos.Line >= target.start && pos.Line <= target.end {
				continue // the declaration itself, or a call it makes to itself
			}
			key := rel + ":" + strconv.Itoa(pos.Line) + ":" + strconv.Itoa(pos.Column) + ":" + target.scope
			if seen[key] {
				continue
			}
			seen[key] = true
			out = append(out, useSite{rel: rel, line: pos.Line, col: pos.Column, target: target})
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].sortKey() < out[j].sortKey() })
	return out
}

// changedFiles lists every path that differs between base and the working
// tree, including files git does not track yet. A review that skips a new file
// because it was never added is worse than one that never ran.
func changedFiles(repo, base string) ([]change, error) {
	tracked, err := gitOutput(repo, "diff", "--name-status", "-z", base)
	if err != nil {
		return nil, err
	}
	byPath := map[string]change{}
	for _, c := range parseNameStatus(tracked) {
		byPath[c.path] = c
	}
	if untracked, uerr := gitOutput(repo, "ls-files", "--others", "--exclude-standard", "-z"); uerr == nil {
		for _, p := range splitNUL(untracked) {
			p = filepath.ToSlash(p)
			if _, seen := byPath[p]; !seen {
				byPath[p] = change{path: p, status: "A"}
			}
		}
	}
	out := make([]change, 0, len(byPath))
	for _, c := range byPath {
		out = append(out, c)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].path < out[j].path })
	return out, nil
}

// parseNameStatus reads the NUL-separated form of `git diff --name-status`.
// Rename and copy records carry two paths; the second one is where the code
// lives now, which is the one a reviewer reads.
func parseNameStatus(s string) []change {
	fields := splitNUL(s)
	var out []change
	for i := 0; i < len(fields); i++ {
		status := fields[i]
		if status == "" {
			continue
		}
		want := 1
		if status[0] == 'R' || status[0] == 'C' {
			want = 2
		}
		if i+want >= len(fields) {
			break
		}
		path := fields[i+want]
		i += want
		out = append(out, change{path: filepath.ToSlash(path), status: status})
	}
	return out
}

// hunkRanges returns the working-tree line spans the diff touches in path. A
// hunk that only deletes lines has no working-tree span of its own, so it is
// reported as the single line the deletion sits after, which is where the
// reviewer has to look.
func hunkRanges(repo, base, path string) ([]lineRange, error) {
	out, err := gitOutput(repo, "diff", "-U0", "--no-color", base, "--", path)
	if err != nil {
		return nil, err
	}
	var ranges []lineRange
	for _, line := range strings.Split(out, "\n") {
		if !strings.HasPrefix(line, "@@") {
			continue
		}
		r, ok := parseHunkHeader(line)
		if ok {
			ranges = append(ranges, r)
		}
	}
	return mergeRanges(ranges), nil
}

// removedRanges returns the base-side spans a diff deletes from path.
//
// These are the lines that no longer exist, so they have no working-tree span
// and hunkRanges cannot report them. Their history is the interesting kind:
// the reason a line was added is the reason not to delete it, and a diff that
// only removes code carries none of that on its face.
func removedRanges(repo, base, path string) ([]lineRange, error) {
	out, err := gitOutput(repo, "diff", "-U0", "--no-color", base, "--", path)
	if err != nil {
		return nil, err
	}
	var ranges []lineRange
	for _, line := range strings.Split(out, "\n") {
		if !strings.HasPrefix(line, "@@") {
			continue
		}
		if r, ok := parseRemovedHunkHeader(line); ok {
			ranges = append(ranges, r)
		}
	}
	return mergeRanges(ranges), nil
}

// parseRemovedHunkHeader reads the "-start,count" half. A count of zero means
// the hunk adds without removing, and there is nothing deleted to trace.
func parseRemovedHunkHeader(line string) (lineRange, bool) {
	i := strings.Index(line, "-")
	if i < 0 {
		return lineRange{}, false
	}
	rest := line[i+1:]
	if j := strings.IndexAny(rest, " @+"); j >= 0 {
		rest = rest[:j]
	}
	startStr, countStr, hasCount := strings.Cut(rest, ",")
	start, err := strconv.Atoi(startStr)
	if err != nil || start < 1 {
		return lineRange{}, false
	}
	count := 1
	if hasCount {
		count, err = strconv.Atoi(countStr)
		if err != nil {
			return lineRange{}, false
		}
	}
	if count == 0 {
		return lineRange{}, false
	}
	return lineRange{start: start, end: start + count - 1}, true
}

// parseHunkHeader reads the "+start,count" half of a unified diff hunk header.
func parseHunkHeader(line string) (lineRange, bool) {
	i := strings.Index(line, "+")
	if i < 0 {
		return lineRange{}, false
	}
	rest := line[i+1:]
	if j := strings.IndexAny(rest, " @"); j >= 0 {
		rest = rest[:j]
	}
	startStr, countStr, hasCount := strings.Cut(rest, ",")
	start, err := strconv.Atoi(startStr)
	if err != nil {
		return lineRange{}, false
	}
	count := 1
	if hasCount {
		count, err = strconv.Atoi(countStr)
		if err != nil {
			return lineRange{}, false
		}
	}
	if count == 0 {
		if start < 1 {
			start = 1
		}
		return lineRange{start: start, end: start}, true
	}
	return lineRange{start: start, end: start + count - 1}, true
}

// mergeRanges sorts spans and folds overlapping or touching ones together, so
// one declaration spanning several hunks is asked about once.
func mergeRanges(in []lineRange) []lineRange {
	if len(in) == 0 {
		return nil
	}
	sorted := append([]lineRange(nil), in...)
	sort.Slice(sorted, func(i, j int) bool {
		if sorted[i].start != sorted[j].start {
			return sorted[i].start < sorted[j].start
		}
		return sorted[i].end < sorted[j].end
	})
	out := []lineRange{sorted[0]}
	for _, r := range sorted[1:] {
		last := &out[len(out)-1]
		if r.start <= last.end+1 {
			if r.end > last.end {
				last.end = r.end
			}
			continue
		}
		out = append(out, r)
	}
	return out
}

// loadModule type-checks the module rooted at repo. Errors are returned as
// notes: a provider that fails entirely because one package is broken is
// useless on exactly the changes people most want reviewed.
func loadModule(repo string) (*index, []string) {
	idx := &index{byAbs: map[string]*fileUnit{}, fallback: token.NewFileSet()}
	pkgs, _, err := goload.LoadTypedPackages(filepath.Join(repo, "go.mod"), true)
	if err != nil {
		return idx, []string{fmt.Sprintf("module did not load: %v; symbol resolution is limited to syntax", err)}
	}
	sorted := append([]*packages.Package(nil), pkgs...)
	sort.Slice(sorted, func(i, j int) bool { return sorted[i].ID < sorted[j].ID })
	idx.pkgs = sorted

	var notes []string
	broken := 0
	for _, p := range sorted {
		if len(p.Errors) > 0 {
			broken++
		}
		if p.Fset != nil && idx.fset == nil {
			idx.fset = p.Fset
		}
		for i, f := range p.CompiledGoFiles {
			if i >= len(p.Syntax) {
				break
			}
			abs, aerr := filepath.Abs(f)
			if aerr != nil {
				continue
			}
			if _, seen := idx.byAbs[abs]; seen {
				continue
			}
			idx.byAbs[abs] = &fileUnit{abs: abs, pkg: p, syntax: p.Syntax[i], fset: p.Fset}
		}
	}
	if broken > 0 {
		notes = append(notes, fmt.Sprintf("%d package(s) failed to type-check; their callers and types were not resolved", broken))
		for _, msg := range goload.PackagesErrors(sorted) {
			notes = append(notes, "type-check: "+msg)
		}
	}
	if idx.fset == nil {
		idx.fset = idx.fallback
	}
	return idx, notes
}

// declsIn returns every top-level declaration in the file, in source order. A
// grouped var or const block yields one declaration per spec so a one-line
// change inside a fifty-entry block names the entry it touched.
func declsIn(u *fileUnit, rel, dir string) []*decl {
	if u == nil || u.syntax == nil {
		return nil
	}
	line := func(p token.Pos) int { return u.fset.Position(p).Line }
	var out []*decl
	for _, d := range u.syntax.Decls {
		switch n := d.(type) {
		case *ast.FuncDecl:
			start := n.Pos()
			if n.Doc != nil {
				start = n.Doc.Pos()
			}
			recv := receiverName(n)
			name := n.Name.Name
			kind := "func"
			if recv != "" {
				name = recv + "." + n.Name.Name
				kind = "method"
			}
			out = append(out, &decl{
				rel: rel, symbol: name, scope: qualify(dir, name), kind: kind,
				receiver: recv, start: line(start), end: line(n.End()),
				exported: n.Name.IsExported(), fn: n, unit: u,
			})
		case *ast.GenDecl:
			if n.Tok == token.IMPORT {
				continue
			}
			out = append(out, genDecls(u, n, rel, dir, line)...)
		}
	}
	return out
}

func genDecls(u *fileUnit, n *ast.GenDecl, rel, dir string, line func(token.Pos) int) []*decl {
	kind := strings.ToLower(n.Tok.String())
	groupStart := n.Pos()
	if n.Doc != nil {
		groupStart = n.Doc.Pos()
	}
	var out []*decl
	for _, spec := range n.Specs {
		for _, name := range specNames(spec) {
			start, end := line(spec.Pos()), line(spec.End())
			if len(n.Specs) == 1 {
				start, end = line(groupStart), line(n.End())
			} else if doc := specDoc(spec); doc != nil {
				start = line(doc.Pos())
			}
			out = append(out, &decl{
				rel: rel, symbol: name, scope: qualify(dir, name), kind: kind,
				start: start, end: end, exported: ast.IsExported(name), unit: u,
			})
		}
	}
	return out
}

// resolveObject attaches the type-checker object for a declaration. It stays
// nil when the package did not type-check, and every stage that needs an
// object skips such a declaration rather than guessing by name.
func resolveObject(d *decl) {
	if d.unit == nil || d.unit.pkg == nil || d.unit.pkg.TypesInfo == nil {
		return
	}
	if d.fn != nil {
		if obj, ok := d.unit.pkg.TypesInfo.Defs[d.fn.Name]; ok {
			d.obj = obj
		}
		return
	}
	if d.unit.pkg.Types == nil {
		return
	}
	// Anything else a changed hunk can enclose is a top-level type, var, or
	// const, and those all live in the package scope under their own name.
	d.obj = d.unit.pkg.Types.Scope().Lookup(d.symbol)
}

const mappingFixture = `package fix

