// unit returns the loaded file, parsing it directly when the loader did not
// produce one. A file added but not yet compiling still gets its enclosing
// declarations mapped, without types.
func (idx *index) unit(abs string) *fileUnit {
	if u, ok := idx.byAbs[abs]; ok {
		return u
	}
	src, err := os.ReadFile(abs)
	if err != nil {
		return nil
	}
	syntax, perr := goparser.ParseFile(idx.fallback, abs, src, goparser.ParseComments)
	if syntax == nil && perr != nil {
		return nil
	}
	u := &fileUnit{abs: abs, syntax: syntax, fset: idx.fallback}
	idx.byAbs[abs] = u
	return u
}

// details is the Go-shaped half of an expansion. The consumer passes it
// through and renders it generically, which is why nothing language-specific
// belongs in any other field.
func (d *decl) details() map[string]string {
	m := map[string]string{
		"kind":         d.kind,
		"exported":     strconv.FormatBool(d.exported),
		"changedLines": strconv.Itoa(d.changed),
	}
	if d.receiver != "" {
		m["receiver"] = d.receiver
	}
	if d.unit != nil && d.unit.pkg != nil {
		m["package"] = d.unit.pkg.PkgPath
	}
	return m
}

// expandEnclosing emits the whole declaration each changed hunk sits inside.
// A hunk without it cannot be judged at all, which is why this role is first.
func (b *builder) expandEnclosing() {
	for _, d := range b.decls {
		b.add(Expansion{
			Role:      RoleEnclosing,
			Priority:  priorityFor(d),
			Symbol:    d.symbol,
			Scope:     d.scope,
			File:      d.rel,
			StartLine: d.start,
			EndLine:   d.end,
			Content:   b.slice(d.rel, d.start, d.end),
			Details:   d.details(),
		})
	}
}

// counts renders a count map with its keys sorted, so the same envelope prints
// the same line every time.
func counts(m map[string]int) string {
	if len(m) == 0 {
		return "none"
	}
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	parts := make([]string, 0, len(keys))
	for _, k := range keys {
		parts = append(parts, fmt.Sprintf("%s %d", k, m[k]))
	}
	return strings.Join(parts, ", ")
}

func sortedUnique(in []string) []string {
	if len(in) == 0 {
		return nil
	}
	seen := map[string]bool{}
	out := make([]string, 0, len(in))
	for _, s := range in {
		if s == "" || seen[s] {
			continue
		}
		seen[s] = true
		out = append(out, s)
	}
	sort.Strings(out)
	return out
}

func isGeneratedName(base string) bool {
	if generatedNames[base] {
		return true
	}
	for _, s := range generatedNameSuffixes {
		if strings.HasSuffix(base, s) {
			return true
		}
	}
	for _, p := range generatedNamePrefixes {
		if strings.HasPrefix(base, p) && strings.HasSuffix(base, ".go") {
			return true
		}
	}
	return false
}

// gitOutput runs a git command and returns its stdout. Stderr is folded into
// the error so a caller reporting a note says what git said.
func gitOutput(root string, args ...string) (string, error) {
	cmd := gitCmd(root, args...)
	var errBuf bytes.Buffer
	cmd.Stderr = &errBuf
	out, err := cmd.Output()
	if err != nil {
		msg := strings.TrimSpace(errBuf.String())
		if msg == "" {
			msg = err.Error()
		}
		return "", fmt.Errorf("git %s: %s", strings.Join(args, " "), msg)
	}
	return string(out), nil
}

// builder carries the state of one Build call. Every stage appends to it and
// nothing reads back, which is what keeps the output a function of the
// revision alone.
type builder struct {
	repo      string
	base      string
	idx       *index
	files     []File
	exps      []Expansion
	notes     []string
	decls     []*decl
	ranges    map[string][]lineRange
	lines     map[string][]string
	declCache map[string][]*decl
}

// mergeBase resolves the point the change is measured from: the merge base of
// ref and HEAD. A ref with no common ancestor, and a repository with no HEAD,
// fall back to the ref itself so a first commit still produces an envelope.
func mergeBase(repo, ref string) (string, error) {
	if out, err := gitOutput(repo, "merge-base", ref, "HEAD"); err == nil {
		if sha := strings.TrimSpace(out); sha != "" {
			return sha, nil
		}
	}
	out, err := gitOutput(repo, "rev-parse", "--verify", ref+"^{commit}")
	if err != nil {
		return "", err
	}
	return strings.TrimSpace(out), nil
}

// sourceLines reads a working-tree file once and keeps its lines for slicing.
func (b *builder) sourceLines(rel string) []string {
	if lines, ok := b.lines[rel]; ok {
		return lines
	}
	data, err := os.ReadFile(filepath.Join(b.repo, filepath.FromSlash(rel)))
	if err != nil {
		b.lines[rel] = nil
		return nil
	}
	lines := strings.Split(strings.ReplaceAll(string(data), "\r\n", "\n"), "\n")
	b.lines[rel] = lines
	return lines
}

// slice returns lines start..end of a file, inclusive and 1-based.
func (b *builder) slice(rel string, start, end int) string {
	lines := b.sourceLines(rel)
	if len(lines) == 0 || start < 1 {
		return ""
	}
	if end > len(lines) {
		end = len(lines)
	}
	if start > end {
		return ""
	}
	return strings.Join(lines[start-1:end], "\n") + "\n"
}

// changedByPos indexes the changed declarations by the position of the object
// they declare. Positions are the identity used throughout the expansion
// stages: the loader type-checks a package and its test variant separately, so
// the same declaration yields two objects, and only their shared declaration
// position ties them together.
func (b *builder) changedByPos() map[token.Pos]*decl {
	out := map[token.Pos]*decl{}
	for _, d := range b.decls {
		if d.obj != nil {
			out[d.obj.Pos()] = d
		}
	}
	return out
}

// declFor locates the declaration that defines an object. Positions come from
// the loader's shared file set, which is what lets an object found in one
// package variant point at a file another variant parsed.
func (b *builder) declFor(obj types.Object) *decl {
	if obj == nil || b.idx == nil || b.idx.fset == nil {
		return nil
	}
	pos := b.idx.fset.Position(obj.Pos())
	rel, ok := b.rel(pos.Filename)
	if !ok {
		return nil
	}
	return b.enclosingAt(rel, pos.Line)
}

func fixtureDecls(t *testing.T) []*decl {
	t.Helper()
	dir := t.TempDir()
	path := filepath.Join(dir, "fix.go")
	if err := os.WriteFile(path, []byte(mappingFixture), 0o644); err != nil {
		t.Fatal(err)
	}
	idx := &index{byAbs: map[string]*fileUnit{}, fallback: token.NewFileSet()}
	unit := idx.unit(path)
	if unit == nil || unit.syntax == nil {
		t.Fatal("fixture did not parse")
	}
	return declsIn(unit, "pkg/fix.go", "pkg")
}

func specNames(spec ast.Spec) []string {
	switch s := spec.(type) {
	case *ast.TypeSpec:
		return []string{s.Name.Name}
	case *ast.ValueSpec:
		var out []string
		for _, n := range s.Names {
			out = append(out, n.Name)
		}
		return out
	}
	return nil
}

