func gitRun(t *testing.T, dir string, args ...string) {
	t.Helper()
	cmd := exec.Command("git", append([]string{"-C", dir}, args...)...)
	// Pinned dates keep the history role's content a function of the fixture
	// rather than of the clock the test ran on.
	cmd.Env = append(analyzer.SanitizedGitEnv(),
		"GIT_AUTHOR_DATE=2026-01-02T03:04:05+00:00",
		"GIT_COMMITTER_DATE=2026-01-02T03:04:05+00:00")
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("git %s: %v\n%s", strings.Join(args, " "), err, out)
	}
}

// expand fills the envelope with the code around the change, in the order the
// consumer ranks the roles.
func (b *builder) expand() {
	if len(b.decls) == 0 {
		return
	}
	b.expandEnclosing()
	b.expandUses()
	b.expandTypes()
	b.expandSiblings()
	b.expandHistory()
}

// declsForRel returns the top-level declarations of any file in the module,
// parsed once and kept. It is how an expansion found by position reports the
// declaration it sits in.
func (b *builder) declsForRel(rel string) []*decl {
	if ds, cached := b.declCache[rel]; cached {
		return ds
	}
	abs := filepath.Join(b.repo, filepath.FromSlash(rel))
	ds := declsIn(b.idx.unit(abs), rel, path.Dir(rel))
	b.declCache[rel] = ds
	return ds
}

// repoRoot returns the absolute top level of the work tree containing dir.
func repoRoot(dir string) (string, error) {
	out, err := gitOutput(dir, "rev-parse", "--show-toplevel")
	if err != nil {
		return "", err
	}
	top := strings.TrimSpace(out)
	if top == "" {
		return "", fmt.Errorf("git rev-parse --show-toplevel returned nothing for %s", dir)
	}
	return filepath.Clean(top), nil
}

// countChanged sums the lines of a declaration the diff touched. It feeds the
// priority hint, where a heavily rewritten function outranks a one-line edit.
func (d *decl) countChanged(ranges []lineRange) int {
	total := 0
	for _, r := range ranges {
		lo, hi := max(r.start, d.start), min(r.end, d.end)
		if lo <= hi {
			total += hi - lo + 1
		}
	}
	return total
}

// priorityFor scores a declaration within its role. Exported symbols outrank
// unexported ones, and a heavily rewritten declaration outranks a one-line
// edit. The scale is local to a role; the consumer never compares across two.
func priorityFor(d *decl) int {
	p := 50
	if d.exported {
		p += 30
	}
	p += min(d.changed, 20)
	return p
}

// declLess orders declarations by where they live, so every stage that walks
// them emits in the same order on every run.
func declLess(a, c *decl) bool {
	if a.rel != c.rel {
		return a.rel < c.rel
	}
	if a.start != c.start {
		return a.start < c.start
	}
	return a.symbol < c.symbol
}

func rolesOf(env *Envelope) []string {
	seen := map[string]bool{}
	var out []string
	for _, e := range env.Expansions {
		if !seen[string(e.Role)] {
			seen[string(e.Role)] = true
			out = append(out, string(e.Role))
		}
	}
	return out
}

// roleRank orders expansions in the emitted JSON. It mirrors the consumer's
// own ranking so the output reads in the order it will be spent, and it has no
// effect on what the consumer keeps.
var roleRank = map[Role]int{
	RoleEnclosing: 0,
	RoleCaller:    1,
	RoleType:      2,
	RoleSibling:   3,
	RoleTest:      4,
	RoleHistory:   5,
}

