func writeFile(t *testing.T, dir, rel, content string) {
	t.Helper()
	p := filepath.Join(dir, filepath.FromSlash(rel))
	if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(p, []byte(content), 0o644); err != nil {
		t.Fatal(err)
	}
}

// declCovering returns the changed declaration a line span falls in, if the
// span sits inside one.
func (b *builder) declCovering(rel string, r lineRange) *decl {
	for _, d := range b.decls {
		if d.rel == rel && d.overlaps(r) {
			return d
		}
	}
	return nil
}

// rel converts an absolute path to the repo-relative, forward-slash form the
// envelope carries. A path outside the work tree is refused: an absolute path
// in the output would name a machine the reviewer is not on.
func (b *builder) rel(abs string) (string, bool) {
	r, err := filepath.Rel(b.repo, abs)
	if err != nil || r == ".." || strings.HasPrefix(r, ".."+string(filepath.Separator)) {
		return "", false
	}
	return filepath.ToSlash(r), true
}

// useSite is one place the code reads a changed symbol, found through the type
// checker. Name matching would also find the string "Insert" in an unrelated
// package, and a reviewer who is shown one wrong call site stops trusting all
// of them.
type useSite struct {
	rel    string
	line   int
	col    int
	target *decl
}

// index is the loaded module: every package variant the loader produced, and
// a lookup from an absolute file path to the one package variant that owns it.
// Test variants re-list the same files, so the owner is picked by sorted
// package ID to keep one file mapping to one syntax tree on every run.
type index struct {
	fset     *token.FileSet
	pkgs     []*packages.Package
	byAbs    map[string]*fileUnit
	fallback *token.FileSet
}

func contextCommand(args []string) error {
	positional, flags := parseFlags(args, contextFlags)
	root := "."
	if flags["--in"] != "" {
		root = flags["--in"]
	}
	if ref := flags["--changed"]; ref != "" {
		return changedContextCommand(ref, root, positional, flags)
	}
	if len(positional) == 0 {
		return usageErrorf("context needs a symbol, or --changed <ref>\nusage: gorefactor %s",
			getCommands()["context"].usageLine())
	}
	target := positional[0]
	budget := defaultContextBudget
	if flags["--budget"] != "" {
		n, err := strconv.Atoi(flags["--budget"])
		if err != nil || n < 200 {
			return usageErrorf("--budget requires an integer >= 200")
		}
		budget = n
	}

	pack, err := buildContextPack(target, root, budget)
	if err != nil {
		return err
	}
	if flags["--json"] != "" {
		emitEnvelope(true, "", pack)

		return nil
	}
	fmt.Print(renderContextPack(pack))
	return nil
}

// wholeFileRange covers a file the diff reports without hunks, such as one
// that git has not tracked yet.
func (b *builder) wholeFileRange(rel string) []lineRange {
	n := len(b.sourceLines(rel))
	if n == 0 {
		return nil
	}
	return []lineRange{{start: 1, end: n}}
}

// enclosingAt returns the declaration containing a line of a file.
func (b *builder) enclosingAt(rel string, line int) *decl {
	for _, d := range b.declsForRel(rel) {
		if d.start <= line && line <= d.end {
			return d
		}
	}
	return nil
}

// isChanged reports whether a declaration is one the diff touched.
func (b *builder) isChanged(d *decl) bool {
	for _, c := range b.decls {
		if c == d || (c.rel == d.rel && c.symbol == d.symbol) {
			return true
		}
	}
	return false
}

// gitCmd builds a git command targeted at root via -C, with the environment
// scrubbed of the repo-locating GIT_* variables. Under a git hook git exports
// GIT_DIR and GIT_INDEX_FILE pointing at the outer repository; inherited by a
// child process they redirect every diff and rev-parse at the wrong repo.
func gitCmd(root string, args ...string) *exec.Cmd {
	cmd := exec.Command("git", append([]string{"-C", root}, args...)...)
	cmd.Env = analyzer.SanitizedGitEnv()
	return cmd
}

func splitNUL(s string) []string {
	var out []string
	for _, f := range strings.Split(s, "\x00") {
		if f != "" {
			out = append(out, f)
		}
	}
	return out
}

// fileUnit is one Go file with whatever the loader could give for it. pkg and
// syntax are nil for a file that failed to load, which is the case the caller
// keeps working through.
type fileUnit struct {
	abs    string
	pkg    *packages.Package
	syntax *ast.File
	fset   *token.FileSet
}

func specDoc(spec ast.Spec) *ast.CommentGroup {
	switch s := spec.(type) {
	case *ast.TypeSpec:
		return s.Doc
	case *ast.ValueSpec:
		return s.Doc
	}
	return nil
}

// qualify prefixes a symbol with the directory it lives in. The consumer
// treats the result as an opaque string; the shape only has to be stable and
// readable.
func qualify(dir, symbol string) string {
	if dir == "" || dir == "." {
		return symbol
	}
	return dir + "." + symbol
}

func shortSHA(sha string) string {
	if len(sha) > 12 {
		return sha[:12]
	}
	if sha == "" {
		return "(none)"
	}
	return sha
}

// reviewable reports whether a changed file is worth resolving symbols in.
// Machine output and vendored code are listed in the manifest and read by
// nobody, so the work of type-checking them buys nothing.
func (b *builder) reviewable(i int) bool {
	f := b.files[i]
	return strings.HasSuffix(f.Path, ".go") && !f.Generated &&
		f.Class != ClassVendored && f.Class != ClassGenerated
}

// add records an expansion, dropping ones with no content so an empty string
// never reaches the consumer as if it were context.
func (b *builder) add(e Expansion) {
	if strings.TrimSpace(e.Content) == "" {
		return
	}
	b.exps = append(b.exps, e)
}

func hasSymbol(exps []Expansion, name string) bool {
	for _, e := range exps {
		if e.Symbol == name {
			return true
		}
	}
	return false
}

func buildFixture(t *testing.T, dir string) *Envelope {
	t.Helper()
	env, err := Build(Options{Root: dir, BaseRef: "HEAD", Version: "v0.0.0-test"})
	if err != nil {
		t.Fatalf("Build: %v", err)
	}
	return env
}

func isMigration(p, base string) bool {
	for _, seg := range strings.Split(path.Dir(p), "/") {
		if migrationDirs[strings.ToLower(seg)] {
			return true
		}
	}
	return migrationNameRe.MatchString(base)
}

func hasSegment(p, want string) bool {
	for _, seg := range strings.Split(p, "/") {
		if seg == want {
			return true
		}
	}
	return false
}

// logRemovedHistory traces a span that existed at base and does not now. The
// span is interpreted against base rather than the working tree, which is the
// only revision where those line numbers mean anything.
func logRemovedHistory(repo, base, path string, r lineRange, max int) (string, error) {
	spec := fmt.Sprintf("-L%d,%d:%s", r.start, r.end, path)
	return gitOutput(repo, "log", "--no-color", "--date=iso-strict",
		"-n", strconv.Itoa(max), spec, base)
}

// logLineHistory returns the recent history of a line span, capped at max
// revisions. The cap is what keeps this role cheap: a file rewritten fifty
// times would otherwise bury everything else in the envelope.
func logLineHistory(repo, path string, r lineRange, max int) (string, error) {
	spec := fmt.Sprintf("-L%d,%d:%s", r.start, r.end, path)
	return gitOutput(repo, "log", "--no-color", "--date=iso-strict",
		"-n", strconv.Itoa(max), spec)
}

// manifest classifies every changed path.
func (b *builder) manifest(changes []change) {
	for _, c := range changes {
		class, generated := classify(b.repo, c)
		b.files = append(b.files, File{Path: c.path, Class: class, Generated: generated})
	}
}

func symbolsOf(exps []Expansion) []string {
	out := make([]string, 0, len(exps))
	for _, e := range exps {
		out = append(out, e.Symbol)
	}
	return out
}

// generatedHeaderRe matches the Go convention line that marks machine output.
// It is anchored at both ends on purpose: a substring test for "Code
// generated" also matches a file that merely discusses the convention, and
// hiding a hand-written file from the reviewer is the one failure this
// classifier must never make.
var generatedHeaderRe = regexp.MustCompile(
	`^\s*(?://+|/\*+|\*)?\s*Code generated\b.*\bDO NOT EDIT\.?\s*(?:\*/)?\s*$`)

// lockfileNames are dependency lock files. They change constantly and carry no
// reviewable intent of their own.
var lockfileNames = map[string]bool{
	"go.sum": true, "package-lock.json": true, "yarn.lock": true,
	"pnpm-lock.yaml": true, "Cargo.lock": true, "Gemfile.lock": true,
	"poetry.lock": true, "composer.lock": true,
}

func keysOf(m map[string]*decl) []string {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	return out
}

// migrationDirs are the directory names schema migrations conventionally live
// in. A migration reads differently from application code: it runs once, in
// order, against data that already exists.
var migrationDirs = map[string]bool{
	"migrations": true, "migration": true, "migrate": true,
}

// namedType pairs a type with the declaration that defines it, so an
// expansion can report a source span without looking the position up twice.
type namedType struct {
	named *types.Named
	decl  *decl
}

// satisfies reports whether a type or a pointer to it implements an interface.
// The pointer half matters because a method set with pointer receivers only
// satisfies the interface through the pointer.
func satisfies(t *types.Named, it *types.Interface) bool {
	return types.Implements(t, it) || types.Implements(types.NewPointer(t), it)
}

// change is one path the diff reports, with the git status letter that
// produced it. Untracked paths are reported as additions.
type change struct {
	path   string // repo-relative, forward slashes
	status string
}

func receiverName(fn *ast.FuncDecl) string {
	if fn.Recv == nil || len(fn.Recv.List) == 0 {
		return ""
	}
	return goload.ReceiverTypeName(fn.Recv.List[0].Type)
}

// finalNotes sorts and de-duplicates the notes so two runs of the same
// revision report the same unknowns in the same order.
func (b *builder) finalNotes() []string {
	return sortedUnique(b.notes)
}

// sortKey orders a use site by where it sits. The line and column are padded
// so the string compares in numeric order.
func (u useSite) sortKey() string {
	return fmt.Sprintf("%s:%08d:%08d:%s", u.rel, u.line, u.col, u.target.scope)
}

// lineRange is an inclusive 1-based span of lines in the working-tree file.
type lineRange struct {
	start int
	end   int
}

// historyRevisions caps how far back the history role reads per line span.
// A handful of revisions is enough to show that a line was deliberate, and it
// keeps a file rewritten fifty times from burying the rest of the envelope.
const historyRevisions = 3

// siblingsPerInterface caps how many other implementations one interface
// contributes. A widely implemented interface would otherwise answer a
// two-line change with every type in the module.
const siblingsPerInterface = 12

// overlaps reports whether a declaration covers any part of a changed span.
func (d *decl) overlaps(r lineRange) bool {
	return d.start <= r.end && r.start <= d.end
}

func init() {
	registerCommand(Command{
		Name:        "context",
		ReadOnly:    true,
		MCPTool:     true,
		Description: "One-shot LLM context pack for a symbol, or --changed <ref> for a whole change: definition, callers, signature types, tests [--budget N] [--json]",
		Usage:       "context <Symbol|Receiver:Method> [--budget N] [--in path] [--json] | context --changed <ref> [--in path] [--json]",
		MinArgs:     0,
		MaxArgs:     1,
		Flags:       contextFlags,
		Run:         contextCommand,
	})
}

// headerScanLines bounds how far into a file the header is looked for. The
// convention puts it above the package clause, so anything deeper is prose.
const headerScanLines = 40

// migrationNameRe matches the numbered-prefix convention most migration tools
// write, such as 000123_add_users.up.sql.
var migrationNameRe = regexp.MustCompile(`^[0-9]{3,}[_-].+\.(sql|go)$`)

// callerContextLines is how much surrounding code a call site carries. A call
// alone does not say what it is guarding or what it does with the result.
const callerContextLines = 2

func TestContextPackSections(t *testing.T) {
	t.Chdir(t.TempDir())
	writeContextFixture(t)

	out := captureStdout(t, func() {
		if err := contextCommand([]string{"Validate"}); err != nil {
			t.Errorf("context: %v", err)
		}
	})
	for _, want := range []string{
		"── Validate (order.go:10) ──",
		"// Validate checks an order for sanity.",
		"func Validate(o Order) error {",
		"── callers (1) ──",
		"func process(o Order)",
		"> 18: \t_ = Validate(o)",
		"── signature types ──",
		"type Order struct {",
		"── tests ──",
		"TestValidate",
	} {
		if !strings.Contains(out, want) {
			t.Errorf("context output missing %q:\n%s", want, out)
		}
	}
}

func TestContextJSONShape(t *testing.T) {
	t.Chdir(t.TempDir())
	writeContextFixture(t)

	out := captureStdout(t, func() {
		if err := contextCommand([]string{"Validate", "--json"}); err != nil {
			t.Errorf("context --json: %v", err)
		}
	})
	var pack contextPack
	decodeEnvelope(t, out, &pack)
	if pack.Symbol != "Validate" || pack.File != "order.go" || pack.Line != 10 {
		t.Fatalf("unexpected header: %+v", pack)
	}
	if pack.Doc != "Validate checks an order for sanity." {
		t.Fatalf("doc = %q", pack.Doc)
	}
	if len(pack.Callers) != 1 || pack.Callers[0].Name != "process" {
		t.Fatalf("callers = %+v", pack.Callers)
	}
	if len(pack.Types) != 1 || pack.Types[0].Name != "Order" {
		t.Fatalf("types = %+v", pack.Types)
	}
	if len(pack.Tests) != 1 || pack.Tests[0] != "TestValidate" {
		t.Fatalf("tests = %+v", pack.Tests)
	}
}

func TestContextBudgetTruncates(t *testing.T) {
	t.Chdir(t.TempDir())
	writeContextFixture(t)

	out := captureStdout(t, func() {
		if err := contextCommand([]string{"Validate", "--budget", "200", "--json"}); err != nil {
			t.Errorf("context --budget: %v", err)
		}
	})
	var pack contextPack
	decodeEnvelope(t, out, &pack)
	if !pack.Truncated {
		t.Fatalf("budget 200 should force truncation: %+v", pack)
	}
	if len(pack.Notes) == 0 {
		t.Fatal("truncation must leave a note")
	}
	if len(renderContextPack(&pack)) > 200+100 { // small slack for the trailing notes line
		t.Fatalf("rendered pack still exceeds budget: %d chars", len(renderContextPack(&pack)))
	}
	// the definition is the highest-value section and must survive
	if pack.Definition == "" {
		t.Fatal("definition must never be dropped entirely")
	}
}

func TestContextTypeSymbol(t *testing.T) {
	t.Chdir(t.TempDir())
	writeContextFixture(t)

	out := captureStdout(t, func() {
		if err := contextCommand([]string{"Order"}); err != nil {
			t.Errorf("context on type: %v", err)
		}
	})
	if !strings.Contains(out, "// Order is a purchase order.") || !strings.Contains(out, "type Order struct {") {
		t.Fatalf("type context missing definition:\n%s", out)
	}
}

